clear;
clc;
close all;

% Initial speeds in meters per second
initialSpeeds = [10 15 20 25 30];

% Braking acceleration value
% Negative because the vehicle is slowing down
acceleration = -6;

% Time step
dt = 0.01;

% Create figure
figure; %[output:6c26e8db]
hold on; %[output:6c26e8db]
grid on; %[output:6c26e8db]

% Store stopping distances
stoppingDistances = zeros(size(initialSpeeds));

for i = 1:length(initialSpeeds)

    % Starting values
    time = 0;
    velocity = initialSpeeds(i);
    position = 0;

    % Store values for plotting
    timeValues = time;
    positionValues = position;

    % Time-stepped simulation
    while velocity > 0
        velocity = velocity + acceleration * dt;

        if velocity < 0
            velocity = 0;
        end

        position = position + velocity * dt;
        time = time + dt;

        timeValues(end + 1) = time;
        positionValues(end + 1) = position;
    end

    % Save stopping distance
    stoppingDistances(i) = position;

    % Plot distance over time
    plot(timeValues, positionValues, 'LineWidth', 2); %[output:6c26e8db]
end

xlabel('Time (seconds)'); %[output:6c26e8db]
ylabel('Distance Traveled (meters)'); %[output:6c26e8db]
title('Vehicle Braking Distance Simulation'); %[output:6c26e8db]
legend('10 m/s', '15 m/s', '20 m/s', '25 m/s', '30 m/s'); %[output:6c26e8db]

% Create results table
resultsTable = table(initialSpeeds', stoppingDistances', ...
    'VariableNames', {'Initial_Speed_m_per_s', 'Stopping_Distance_m'});

disp(resultsTable); %[output:14fce7bf]

disp("Interpretation:"); %[output:155c7b9c]
disp("Higher initial speeds lead to longer stopping distances."); %[output:98dff984]
disp("This shows that driving faster makes it harder to stop quickly and increases safety risk."); %[output:425321c6]

